// Regenerates lib/src/bindings.g.dart from the C header: dart run tool/ffigen.dart
import 'dart:io';

import 'package:ffigen/ffigen.dart';

const _macros = {'TAPIRSCAN_ABI_VERSION', 'TAPIRSCAN_ABSENT'};

Future<void> main() async {
  final root = Uri.directory(Directory.current.path);
  final header = root.resolve('../c/include/tapirscan.h');
  await FfiGenerator(
    input: Input(entryPoints: [header]),
    output: Output(
      dart: DartOutput(path: root.resolve('lib/src/bindings.g.dart')),
      preamble:
          '// Generated by tool/ffigen.dart from bindings/c/include/tapirscan.h. Do not edit.\n'
          '// ignore_for_file: type=lint, unused_field',
      style: const NativeExternalBindings(
        assetId: 'package:tapirscan/src/bindings.g.dart',
      ),
    ),
    visitors: [
      Visitor(
        func: (node) => node.isIncluded = node.name.startsWith('tapirscan_'),
        struct: (node) => node.isIncluded = node.name.startsWith('tapirscan_'),
        enumClass: (node) {
          node.isIncluded = node.name.startsWith('tapirscan_');
          node.style = EnumStyle.intConstants;
        },
        macroConstant: (node) => node.isIncluded = _macros.contains(node.name),
      ),
    ],
  ).generate();
}
